const generateStyles = (props: AssetIconProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AssetIconProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    position: "relative",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: 0,
    margin: 0,
    overflow: "hidden",
    backgroundColor: theme.color.asset.userInterfaceWeak,
    color: theme.color.asset.userInterface,

    [`&.${AssetIconClasses.outline}`]: {
      backgroundColor: "transparent !important",
      border: `${theme.toRem(theme.border.width.sm)} dashed ${theme.color.border.strong}`,
      color: `${theme.color.content.icon} !important`,
      [`&.${AssetIconClasses.lg}`]: {
        width: theme.toRem(32),
        height: theme.toRem(32),
        ...styleSlots?.outlineLg,
      },
      ...styleSlots?.outline,
    },

    [`&.${AssetIconClasses.sm}`]: {
      width: theme.toRem(16),
      height: theme.toRem(16),
      backgroundColor: theme.color.asset.userInterface,
      color: theme.color.asset.userInterfaceWeak,
      [`& .${AssetIconClasses.icon}`]: {
        width: theme.toRem(12),
        height: theme.toRem(12),
        ...styleSlots?.iconSm,
      },
      ...styleSlots?.sm,
    },
    [`&.${AssetIconClasses.md}`]: {
      width: theme.toRem(24),
      height: theme.toRem(24),
      backgroundColor: theme.color.asset.userInterface,
      color: theme.color.asset.userInterfaceWeak,
      [`& .${AssetIconClasses.icon}`]: {
        width: theme.toRem(16),
        height: theme.toRem(16),
        ...styleSlots?.iconMd,
      },
      ...styleSlots?.md,
    },
    [`&.${AssetIconClasses.lg}`]: {
      width: theme.toRem(40),
      height: theme.toRem(40),
      [`& .${AssetIconClasses.icon}`]: {
        width: theme.toRem(16),
        height: theme.toRem(16),
        ...styleSlots?.iconLg,
      },
      ...styleSlots?.lg,
    },
    [`&.${AssetIconClasses.xlg}`]: {
      width: theme.toRem(64),
      height: theme.toRem(64),
      [`& .${AssetIconClasses.icon}`]: {
        width: theme.toRem(24),
        height: theme.toRem(24),
        ...styleSlots?.iconXlg,
      },
      ...styleSlots?.xlg,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAssetIcon = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AssetIconProps>((props) => generateStyles(props));
